def.body:
mtime = (File.info(file)).modification_time
cached = @templates[file]?

if cached && (cached[:mtime] == mtime)
  return cached[:template]
end

template = @env.from_string(File.read(file))
@templates[file] = {mtime: mtime, template: template}
template

@host_name = host_name
@grains = grains
@pillar = pillar
@namespace = namespace
@path = path
@steps = steps

with_debug_run do
  build_stack
end

@stack

output = begin
  (@context.template(file)).render(data)
rescue e : Exception
  @log.error do "Error while compiling template #{file}" end
  @log.error do e.message end
  raise(RenderError.new("#{file}: #{e.message}", cause: e))
end

@log.debug do "Compiled: #{file}" end

output
